"OLAYLAR_ORTACAG_ORTADOGU:1285-01-01:0":{"b": ["استولى قلاوون على قلعة المرقب (مرقب) من الإسبتارية وأزال هذه القوة الصليبية؛ وسقط آخر معقل صليبي كبير في المحيط القريب من كونتية طرابلس (684/1285).", "722b884f"], "d": ["استولى قلاوون على قلعة المرقب (مرقب) من الإسبتارية وأزال هذه القوة الصليبية؛ وسقط آخر معقل صليبي كبير في المحيط القريب من كونتية طرابلس (684/1285).", "722b884f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1287-01-01:0":{"b": ["توفي الكونت بوهيموند السابع؛ وأضعف النزاع على الوراثة بين أخته لوسيا وكومونة المدينة التي دعمها الجنويون الكونتية، وأتاح الفرصة لقلاوون.", "e68819ba"], "d": ["توفي الكونت بوهيموند السابع؛ وأضعف النزاع على الوراثة بين أخته لوسيا وكومونة المدينة التي دعمها الجنويون الكونتية، وأتاح الفرصة لقلاوون.", "e68819ba"]},
"OLAYLAR_ORTACAG_ORTADOGU:1289-04-26:0":{"b": ["فتح قلاوون طرابلس الشام؛ وانتهت كونتية طرابلس", "2c912cc3"], "d": ["فتح قلاوون طرابلس الشام؛ وانتهت كونتية طرابلس", "2c912cc3"]},
"OLAYLAR_ORTACAG_ORTADOGU:1291-07-01:0":{"b": ["انتقال صيدا إلى المماليك (انسحاب فرسان الداوية)", "2339a488"], "d": ["إثر فتح عكا (690/1291) لجأ فرسان الداوية الذين غادروها إلى صيدا؛ وانتقلت المدينة إلى أيدي المماليك في رجب 690 / يوليو 1291 وهُدمت أسوارها.", "4c9103e0"]},
